USE caffe_camillo_colombi;
SELECT c.id,o.id,r.id,e.id,'Camillo Origem','camillo-origem','Um café artesanal pensado para quem quer começar pela essência da casa.','Este lote é apresentado como uma homenagem às origens escolhidas para o Caffè Camillo Colombi. O texto é demonstrativo e pode ser substituído pela história real da propriedade quando fornecida pela marca.','Chocolate, castanhas, caramelo','arabica',34.90,1,'/assets/images/package-arabica.svg',o.image_url FROM categories c,origins o,roasts r,essences e WHERE c.slug='cafes' AND o.slug='sao-gabriel-da-palha' AND r.name='Torra média' AND e.slug='tradicional' LIMIT 1;
SELECT c.id,o.id,r.id,e.id,'Camillo Intenso','camillo-intenso','Torra forte para uma xícara de presença marcante.','Um perfil construído para valorizar corpo e intensidade. A origem e a narrativa exibidas aqui são demonstrativas até que a equipe forneça o texto oficial do lote.','Cacau, caramelo queimado, especiarias','conilon',49.90,1,'/assets/images/package-conilon.svg',o.image_url FROM categories c,origins o,roasts r,essences e WHERE c.slug='cafes' AND o.slug='domingos-martins' AND r.name='Torra forte' AND e.slug='tradicional' LIMIT 1;
SELECT c.id,o.id,r.id,e.id,'Camillo Cacau','camillo-cacau','Edição especial com perfil aromático de cacau.','Uma edição especial pensada para unir café e uma sensação achocolatada. O texto é conceitual e deve ser validado pela marca antes da publicação comercial.','Cacau, chocolate amargo, noz','mixed',64.90,1,'/assets/images/package-cacau.svg',o.image_url FROM categories c,origins o,roasts r,essences e WHERE c.slug='cafes' AND o.slug='sao-gabriel-da-palha' AND r.name='Torra média' AND e.slug='cacau' LIMIT 1;
