INSERT IGNORE INTO product_variants(product_id,grinding_id,weight_grams,price,stock) SELECT p.id,g.id,w.weight,ROUND(p.base_price + (CASE WHEN p.bean_type='arabica' THEN 0 WHEN p.bean_type='mixed' THEN 15 ELSE 30 END) + CASE WHEN w.weight=500 THEN 20 ELSE 0 END + CASE WHEN g.slug='moka' THEN 3 ELSE 0 END,2),CASE WHEN w.weight=250 THEN 18 ELSE 10 END FROM products p CROSS JOIN grindings g CROSS JOIN (SELECT 250 weight UNION ALL SELECT 500) w;
